// Build-time embedded migration bundle.
//
// **AUTO-GENERATED by `scripts/gen-embedded-migrations.ts`.**  Do not
// edit by hand — the codegen rebuilds this file from
// `meta/_journal.json` on every `bun run gen migrations`. The CI
// drift check (`bun run gen migrations --check`) fails if the
// committed file disagrees with the regenerated output.
//
// We import each migration's raw SQL as text and the journal as JSON.
// `bun build --compile` inlines the contents of every imported text /
// JSON asset into the binary, so the runtime never reads the
// filesystem and the engine + migration set ship as a single artifact.
//
// Drift safeguard: `migrate-embedded-bundle.test.ts` re-reads the
// on-disk SQL files at test time and asserts every embedded body's
// SHA-256 matches the file. CI fails loudly if a new migration is
// added but not registered here.

import { createHash } from "node:crypto";
import sql0000BaselineV2 from "./0000_baseline_v2.sql" with { type: "text" };
import sql0001WorkspaceLanguage from "./0001_workspace_language.sql" with { type: "text" };
import sql0002ConnectionStartOwner from "./0002_connection_start_owner.sql" with { type: "text" };
import sql0003TaskSourceMessage from "./0003_task_source_message.sql" with { type: "text" };
import sql0004IntakeAnonymousCollector from "./0004_intake_anonymous_collector.sql" with { type: "text" };
import sql0005SecondBrainContract from "./0005_second_brain_contract.sql" with { type: "text" };
import sql0006KnowledgeReviewDue from "./0006_knowledge_review_due.sql" with { type: "text" };
import sql0007TenantRowSecurity from "./0007_tenant_row_security.sql" with { type: "text" };
import sql0008NotificationChannelFloor from "./0008_notification_channel_floor.sql" with { type: "text" };
import sql0009ConversationVisibility from "./0009_conversation_visibility.sql" with { type: "text" };
import sql0010TenantRowSecurityForce from "./0010_tenant_row_security_force.sql" with { type: "text" };
import journalMeta from "./meta/_journal.json" with { type: "json" };

interface JournalEntry {
  idx: number;
  tag: string;
  when: number;
  breakpoints?: boolean;
}

interface Journal {
  version: string;
  dialect: string;
  entries: JournalEntry[];
}

export interface EmbeddedMigration {
  idx: number;
  tag: string;
  when: number;
  hash: string;
  statements: string[];
}

const SQL_BY_TAG: Record<string, string> = {
  "0000_baseline_v2": sql0000BaselineV2,
  "0001_workspace_language": sql0001WorkspaceLanguage,
  "0002_connection_start_owner": sql0002ConnectionStartOwner,
  "0003_task_source_message": sql0003TaskSourceMessage,
  "0004_intake_anonymous_collector": sql0004IntakeAnonymousCollector,
  "0005_second_brain_contract": sql0005SecondBrainContract,
  "0006_knowledge_review_due": sql0006KnowledgeReviewDue,
  "0007_tenant_row_security": sql0007TenantRowSecurity,
  "0008_notification_channel_floor": sql0008NotificationChannelFloor,
  "0009_conversation_visibility": sql0009ConversationVisibility,
  "0010_tenant_row_security_force": sql0010TenantRowSecurityForce,
};

const journal = journalMeta as unknown as Journal;

function buildBundle(): EmbeddedMigration[] {
  return journal.entries
    .slice()
    .sort((a, b) => a.idx - b.idx)
    .map((e) => {
      const raw = SQL_BY_TAG[e.tag];
      if (raw === undefined) {
        // Caught by `migrate-embedded-bundle.test.ts` in CI long before
        // a binary ships.
        throw new Error(
          `embedded.ts is out of sync with meta/_journal.json: missing SQL for tag '${e.tag}'`,
        );
      }
      const statements = raw
        .split("--> statement-breakpoint")
        .map((s) => s.trim())
        .filter((s) => s.length > 0);
      const hash = createHash("sha256").update(raw).digest("hex");
      return { idx: e.idx, tag: e.tag, when: e.when, hash, statements };
    });
}

export const EMBEDDED_MIGRATIONS: readonly EmbeddedMigration[] = buildBundle();
export const EMBEDDED_JOURNAL: Journal = journal;
